#!/bin/sh
# Claude Code PreToolUse hook: stops Claude editing or writing a generated
# file, and says what to change instead. See docs/tooling.md section 1.5.
#
# A file is generated if it is in a package sqlc generates (the out: lines
# of sqlc.yaml), if it is CHANGELOG.md, which release-please writes, or if
# it starts with Go's marker, a line like "// Code generated by sqlc. DO NOT
# EDIT.", as templ's output will. The paths cover files that don't exist
# yet. Hooks are a guardrail, not a security boundary: CI's
# `make generate-check` is what enforces it.
#
# Claude Code passes the tool call as JSON on stdin. Only
# tool_input.file_path is needed, so sed picks it out and contributors don't
# need jq. Exiting with 2 blocks the call, and shows Claude what this script
# writes to stderr.

file=$(sed -nE 's/.*"file_path"[[:space:]]*:[[:space:]]*"(([^"\\]|\\.)*)".*/\1/p' | head -n 1 | sed 's/\\\(.\)/\1/g')
[ -n "$file" ] || exit 0

# Only files in this repository, by their path in it.
root=${CLAUDE_PROJECT_DIR:-$(pwd)}
case $file in
  "$root"/*) rel=${file#"$root"/} ;;
  /*) exit 0 ;;
  *) rel=$file ;;
esac

reason=
for out in $(sed -n 's/^[[:space:]]*out:[[:space:]]*//p' "$root/sqlc.yaml" 2>/dev/null); do
  case $rel in
    "$out"/*) reason="sqlc generates it from the migrations and queries beside its package: change those, then run make generate, as the db-change skill says" ;;
  esac
done
case $rel in
  CHANGELOG.md) reason="release-please writes it from the commit messages" ;;
esac
if [ -z "$reason" ] && [ -f "$file" ] && head -n 5 "$file" | grep -Eq '^// Code generated .* DO NOT EDIT\.$'; then
  reason="it says it is generated: change what it is generated from, and regenerate it"
fi
[ -n "$reason" ] || exit 0

echo "$rel is a generated file, so don't edit it by hand: $reason." >&2
exit 2
